def _load_value(mem, buf, addr, width):
    """Assemble the value a load at (addr, width) observes.

    mem is an int packing the shared memory bytes little-endian.
    buf is a tuple of (addr, width, value) stores, oldest first.
    For each byte, the youngest buffered store covering it wins.
    """
    v = (mem >> (8 * addr)) & ((1 << (8 * width)) - 1)
    for sa, sw, sv in reversed(buf):
        lo = sa if sa > addr else addr
        hi = sa + sw
        end = addr + width
        if hi > end:
            hi = end
        if lo < hi:
            for b in range(lo, hi):
                shift = 8 * (b - addr)
                byte = (sv >> (8 * (b - sa))) & 0xFF
                v = (v & ~(0xFF << shift)) | (byte << shift)
    return v


def _write_value(mem, addr, width, value):
    """Return mem with width bytes at addr replaced by value (little-endian)."""
    mask = ((1 << (8 * width)) - 1) << (8 * addr)
    return (mem & ~mask) | ((value & ((1 << (8 * width)) - 1)) << (8 * addr))


